'use strict';
const inventoryPages={equipment:1,usable:1,skills:1},INVENTORY_PAGE_SIZE=20;
function inventoryEntries(category){if(category==='equipment')return bagEquipment().map(g=>({id:g.id,name:g.name,level:g.level||1,kind:'gear',gear:g}));if(category==='skills')return Object.entries(player.skillScrolls).filter(([,count])=>count>0).map(([id,count])=>({id,name:WEAPON_SKILLS[id].name,level:WEAPON_SKILLS[id].tier,kind:'skill',count}));return [...Object.entries(POTION_ITEMS).filter(([id])=>player.consumables[id]>0).map(([id,p])=>({id,name:p.name,level:0,kind:'potion',potion:p,count:player.consumables[id]})),...boxStacks().map(b=>({...b,level:boxLevel(b.id),kind:'box'}))]}
function orderedInventory(category){const entries=inventoryEntries(category),order=player.inventoryOrder?.[category]||[];const rank=new Map(order.map((id,i)=>[id,i]));return entries.sort((a,b)=>(rank.get(a.id)??999999)-(rank.get(b.id)??999999))}
function sortInventoryNow(){const category=inventoryCategory,entries=inventoryEntries(category);const rarity={legend:0,epic:1,rare:2,common:3};entries.sort((a,b)=>a.kind.localeCompare(b.kind)||a.name.localeCompare(b.name,'th')||b.level-a.level||(rarity[a.gear?.rarity]??0)-(rarity[b.gear?.rarity]??0));player.inventoryOrder??={};player.inventoryOrder[category]=entries.map(e=>e.id);inventoryPages[category]=1;save();renderInventory(category);toast('เรียงไอเทมแล้ว')}
function renderInventory(category=inventoryCategory){if(!['equipment','usable','skills'].includes(category))return;hideUpgradeTooltip();inventoryCategory=category;document.querySelectorAll('[data-inventory]').forEach(b=>{const selected=b.dataset.inventory===category;b.classList.toggle('selected',selected);b.setAttribute('aria-selected',String(selected))});const grid=$('inventoryGrid');grid.setAttribute('aria-labelledby','tab-'+category);grid.replaceChildren();const entries=orderedInventory(category),pages=Math.max(5,Math.ceil(entries.length/INVENTORY_PAGE_SIZE));inventoryPages[category]=Math.min(inventoryPages[category]||1,pages);const offset=(inventoryPages[category]-1)*INVENTORY_PAGE_SIZE;for(let i=0;i<INVENTORY_PAGE_SIZE;i++){const item=entries[offset+i],cell=document.createElement(item?'button':'div');cell.className='inventory-cell';cell.dataset.position=offset+i+1;if(!item){cell.setAttribute('aria-label','ช่อง '+(offset+i+1)+' ว่าง');grid.append(cell);continue}cell.classList.add('inventory-item');cell.dataset.itemId=item.id;cell.setAttribute('aria-label',item.name);if(item.kind==='gear'){cell.innerHTML=gearIcon(item.gear);cell.style.color=LOOT_RARITIES[item.gear.rarity].color;cell.style.borderColor=LOOT_RARITIES[item.gear.rarity].color;attachLootDetail(cell,{name:item.name,description:gearDescription(item.gear)});cell.onclick=()=>showGearDialog(item.gear)}else if(item.kind==='skill'){const d=WEAPON_SKILLS[item.id];cell.classList.add('skill-scroll');cell.innerHTML=weaponIcon(d.weapon);const tier=document.createElement('small');tier.className='box-level';tier.textContent='ขั้น '+d.tier;cell.append(tier);attachLootDetail(cell,{name:d.name,description:SKILL_KINDS[d.kind]+' · '+weaponSkillText(item.id)});cell.onclick=()=>openWeaponSkillDetail(item.id)}else if(item.kind==='box'){cell.classList.add('loot-box');cell.innerHTML=boxIcon(item.id);appendBoxLevel(cell,item.id);attachLootDetail(cell,{name:item.name,description:boxDescription(item.id)});bindBoxOpening(cell,item.id)}else{cell.classList.add(item.potion.kind+'-potion');const icon=document.createElement('span');icon.className='potion-bottle';cell.append(icon);attachLootDetail(cell,{name:item.name,description:item.potion.description});cell.onclick=()=>showItemDetail(cell,item.potion,item.count,true)}if(item.count){const amount=document.createElement('strong');amount.className='item-count';amount.textContent=item.count;cell.append(amount)}grid.append(cell)}let controls=$('inventoryPageControls');if(!controls){controls=document.createElement('div');controls.id='inventoryPageControls';controls.className='inventory-page-controls';grid.after(controls)}controls.replaceChildren();const sort=document.createElement('button');sort.id='sortInventoryBtn';sort.textContent='เรียงไอเทม';sort.onclick=sortInventoryNow;controls.append(sort);const pager=document.createElement('div');pager.className='inventory-page-buttons';pager.setAttribute('aria-label','หน้ากระเป๋า '+category);for(let page=1;page<=pages;page++){const b=document.createElement('button');b.textContent=page;b.setAttribute('aria-label','หน้ากระเป๋า '+page);b.setAttribute('aria-current',page===inventoryPages[category]?'page':'false');b.classList.toggle('selected',page===inventoryPages[category]);b.onclick=()=>{inventoryPages[category]=page;renderInventory(category)};pager.append(b)}controls.append(pager);$('inventoryHint').textContent=''}
